*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101513;color:#e8e4d8;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#111713}#world{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 38%,rgba(4,8,7,.2) 72%,rgba(4,7,6,.76) 130%);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:88px;padding:0 4.2vw;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,12,11,.75),transparent)}.brand{font-family:Cinzel,serif;font-weight:600;letter-spacing:.23em;font-size:15px;display:flex;align-items:center;gap:12px}.brand-mark{font-size:21px;color:#ceaa69;text-shadow:0 0 16px #f4c078}.brand i{font:500 9px 'DM Sans',sans-serif;color:#a6a99b;letter-spacing:.23em;margin-left:4px}.chapter{font-size:10px;letter-spacing:.2em;color:#d0cbb9}.chapter span{color:#c19c60;padding:0 9px}.icon-btn{width:37px;height:37px;border:1px solid rgba(220,207,171,.32);background:rgba(13,17,14,.32);border-radius:50%;font-size:16px;cursor:pointer;transition:.2s}.icon-btn:hover{background:#c49d60;color:#151713}.hud-left{position:absolute;z-index:3;top:112px;left:4.2vw;display:flex;align-items:center;gap:13px}.portrait{width:56px;height:56px;border:1px solid rgba(215,182,117,.74);background:linear-gradient(145deg,rgba(56,60,48,.94),rgba(17,21,17,.95));display:flex;flex-direction:column;justify-content:center;align-items:center;box-shadow:0 0 20px #0008;clip-path:polygon(15% 0,85% 0,100% 16%,100% 84%,85% 100%,15% 100%,0 84%,0 16%)}.portrait span{font:600 28px Cinzel;color:#e6d9bb;line-height:1}.portrait small{font-size:6px;letter-spacing:.15em;color:#b1a78f;margin-top:3px}.bars{width:224px;display:flex;flex-direction:column;gap:6px}.bar-row{display:flex;align-items:center;gap:7px}.bar-icon{font-size:10px;width:11px;text-align:center}.health .bar-icon{color:#cf6d5e}.stamina .bar-icon{color:#c7c080}.focus .bar-icon{color:#80a8a4}.bar-track{height:9px;position:relative;flex:1;background:rgba(8,10,9,.78);border:1px solid rgba(226,223,199,.22);box-shadow:0 1px 5px #0009;overflow:hidden}.bar-fill{height:100%;transition:width .2s ease}.health .bar-fill{background:linear-gradient(90deg,#7c2725,#c75e4c);box-shadow:0 0 8px #bc493b66}.stamina .bar-track{height:6px}.stamina .bar-fill{background:linear-gradient(90deg,#728052,#c4bd71)}.focus .bar-track{height:5px}.focus .bar-fill{background:linear-gradient(90deg,#456b70,#86aaa5)}.bar-track b{position:absolute;right:4px;top:-2px;font-size:8px;font-weight:500;color:#fff;text-shadow:0 1px 2px #000}.level{font:11px Cinzel;color:#b6ad98;margin-left:3px}.level b{color:#f0e2bd;font-size:15px}.objective{position:absolute;left:4.2vw;top:219px;z-index:3;display:flex;gap:12px;align-items:flex-start}.objective-line{width:2px;height:31px;background:#c4a568;margin-top:2px;box-shadow:0 0 9px #bd9a57}.objective small{font-size:8px;letter-spacing:.23em;color:#c3b38c}.objective p{font:13px Cinzel,serif;margin:5px 0;color:#e8e3d3}.objective em{color:#d5b879;font-style:normal}.bottom-left{position:absolute;z-index:3;left:4.3vw;bottom:39px;display:flex;align-items:center;gap:29px}.resource{display:grid;grid-template-columns:26px auto;grid-template-rows:17px 13px;column-gap:4px;align-items:center}.rune-icon{grid-row:1/3;font-size:22px;color:#e4ca82;text-shadow:0 0 9px #dab768}.resource b{font:16px Cinzel;color:#f1e4c8;letter-spacing:.06em}.resource small,.quick-items small{font-size:7px;letter-spacing:.2em;color:#aaa795}.quick-items{display:flex;align-items:center;gap:8px}.flask{width:32px;height:37px;border:1px solid #c0a770;background:rgba(22,25,19,.76);display:grid;place-items:center;position:relative;color:#d6b66e;font-size:20px;clip-path:polygon(22% 0,78% 0,78% 15%,100% 25%,100% 100%,0 100%,0 25%,22% 15%)}.flask b{position:absolute;right:-5px;bottom:-4px;background:#bf9d61;border-radius:50%;width:14px;height:14px;display:grid;place-items:center;color:#161714;font-size:9px}.quick-items small{line-height:1.55}.boss-hud{position:absolute;z-index:3;bottom:9.5%;left:50%;width:min(440px,54vw);transform:translateX(-50%);opacity:0;transition:opacity .6s;pointer-events:none}.boss-hud.visible{opacity:1}.boss-name{display:flex;align-items:center;gap:10px;margin-bottom:8px}.boss-name>span{font-size:16px;color:#c66c59}.boss-name div{display:flex;flex-direction:column;gap:2px;flex:1}.boss-name small{font-size:7px;letter-spacing:.22em;color:#b7a88f}.boss-name b{font:15px Cinzel;letter-spacing:.13em;color:#e7ded0}.boss-name i{font-size:17px;color:#bf9a61}.boss-track{height:8px;border:1px solid #a68b70;background:#100f0e;box-shadow:0 2px 6px #000}.boss-track div{height:100%;width:100%;background:linear-gradient(90deg,#732c29,#b44a3d);transition:width .25s}.lock-indicator{position:absolute;z-index:3;top:46%;left:50%;transform:translate(-50%,-50%);font:9px Cinzel;letter-spacing:.16em;color:#ead6aa;opacity:0;transition:opacity .2s;text-shadow:0 2px 5px #000}.lock-indicator.visible{opacity:1}.lock-indicator span{font-size:18px;vertical-align:-2px;margin-right:5px}.combat-feed{position:absolute;right:4vw;top:32%;z-index:3;text-align:right;font:11px Cinzel;letter-spacing:.09em;color:#dbb877;text-shadow:0 2px 4px #000;pointer-events:none}.feed-entry{animation:feed 2.4s forwards;margin:6px 0}@keyframes feed{0%{opacity:0;transform:translateX(10px)}10%,65%{opacity:1;transform:none}100%{opacity:0}}.controls-hint{position:absolute;z-index:3;bottom:24px;right:4.2vw;color:#b8b5a8;font-size:8px;letter-spacing:.12em;background:rgba(10,12,10,.5);padding:9px 12px;border:1px solid #e8dfc31c}.controls-hint span{color:#e9dfc7;font-weight:700}.controls-hint i{font-style:normal;color:#b69b6a;padding:0 5px}.interact-prompt{position:absolute;z-index:4;bottom:17%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:10px 16px;background:rgba(12,14,12,.78);border:1px solid #d5bd8455;font:10px Cinzel;letter-spacing:.16em;color:#e9dfc8;opacity:0;transition:opacity .2s;white-space:nowrap}.interact-prompt.visible{opacity:1}.interact-prompt kbd{font:11px Cinzel;background:#c2a265;color:#171814;padding:3px 7px}.crosshair{position:absolute;z-index:3;left:50%;top:50%;transform:translate(-50%,-50%);font-size:14px;color:#eee2bc;text-shadow:0 1px 6px #000;opacity:.65}.overlay{position:absolute;z-index:8;inset:0;background:radial-gradient(ellipse at center,rgba(14,18,16,.48),rgba(7,10,9,.9));display:grid;place-items:center;transition:opacity .55s,visibility .55s;backdrop-filter:blur(3px)}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.title-content{text-align:center;width:min(560px,90vw);animation:rise .9s both}.sigil{color:#c8a265;font-size:25px;text-shadow:0 0 25px #e6ba70;margin-bottom:14px}.eyebrow,.modal-card>small{font-size:9px;letter-spacing:.34em;color:#c6ae7d}.title-content h1{font:500 clamp(42px,7vw,74px)/.98 Cinzel,serif;letter-spacing:.12em;margin:19px 0 18px;text-shadow:0 6px 32px #000}.title-content h1 em{font-weight:400;color:#c6a76d;font-size:.81em;letter-spacing:.27em}.title-content p{font:14px Cinzel;color:#c3c0b5;letter-spacing:.04em;margin:0 auto 34px}.primary-btn{border:1px solid #c9a769;background:linear-gradient(115deg,#b99357,#ddc186);color:#171712;padding:14px 25px;font:600 10px 'DM Sans';letter-spacing:.2em;cursor:pointer;min-width:229px;transition:.2s;box-shadow:0 6px 25px #0006}.primary-btn span{font-size:16px;vertical-align:-2px;margin-left:12px}.primary-btn:hover{filter:brightness(1.13);transform:translateY(-2px);box-shadow:0 8px 30px #c79d4a3b}.title-foot{font-size:7px;letter-spacing:.26em;color:#77796e;margin-top:49px}.title-foot span{color:#bd985d;margin:0 8px}.modal-card{text-align:center;padding:47px 40px;background:linear-gradient(145deg,rgba(27,31,26,.96),rgba(12,15,13,.97));border:1px solid #bba06a77;box-shadow:0 20px 70px #0009;min-width:min(420px,90vw)}.modal-card h2{font:500 36px Cinzel;letter-spacing:.14em;margin:14px 0}.modal-card p{color:#b4b2a7;font:14px Cinzel;margin:0 0 28px}.key-note{font-size:9px;color:#84877e;margin-top:22px;letter-spacing:.08em}.death-card h2{color:#d19a7b}.toast{position:absolute;z-index:7;top:20%;left:50%;transform:translate(-50%,-10px);font:10px Cinzel;letter-spacing:.2em;color:#e8d6ad;background:#111611dd;border:1px solid #c3a06466;padding:10px 18px;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none}
@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@media(max-width:700px){.topbar{height:65px;padding:0 19px}.brand{font-size:12px;gap:7px}.brand i{display:none}.chapter{font-size:8px;letter-spacing:.12em}.icon-btn{width:32px;height:32px}.hud-left{top:78px;left:16px;gap:8px}.portrait{width:43px;height:48px}.portrait span{font-size:23px}.bars{width:min(45vw,190px);gap:5px}.bar-track{height:8px}.level{font-size:9px}.objective{left:18px;top:150px;gap:9px}.objective p{font-size:11px}.objective small{font-size:7px}.bottom-left{left:19px;bottom:20px;gap:17px}.resource b{font-size:13px}.resource small,.quick-items small{font-size:6px}.flask{width:28px;height:32px}.controls-hint{display:none}.mobile-controls{display:block;position:absolute;z-index:4;inset:0;pointer-events:none}.stick-zone{position:absolute;bottom:34px;left:22px;width:126px;height:126px;border-radius:50%;background:#151a1680;border:1px solid #e0d5b62a;pointer-events:auto;touch-action:none}.stick{position:absolute;width:52px;height:52px;left:36px;top:36px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#827f6d,#393c34);border:1px solid #c8b6817a;box-shadow:0 4px 12px #0008}.mobile-actions{position:absolute;right:19px;bottom:29px;width:157px;height:143px;pointer-events:auto}.mobile-actions button{position:absolute;border:1px solid #d2bd805e;border-radius:50%;width:48px;height:48px;background:#151a16c9;color:#e5d7b6;font-size:9px;touch-action:none}.mobile-actions button[data-action=attack]{right:4px;bottom:32px;width:61px;height:61px;font-size:24px;background:#51342fcf}.mobile-actions button[data-action=dodge]{left:7px;bottom:5px}.mobile-actions button[data-action=lock]{right:8px;top:2px}.mobile-actions button[data-action=heal]{left:0;top:22px}.boss-hud{bottom:24%;width:75vw}.boss-name b{font-size:12px}.boss-name small{font-size:6px}.interact-prompt{bottom:25%;font-size:8px;padding:8px 11px}.crosshair{display:none}.combat-feed{top:24%;right:17px;font-size:9px}.title-content p{font-size:12px;max-width:290px}.title-foot{margin-top:35px}.modal-card{padding:37px 20px}.modal-card h2{font-size:30px}}
