import * as THREE from 'three';

const canvas=document.querySelector('#world');
const ui={health:document.querySelector('#health-fill'),healthText:document.querySelector('#health-value'),stamina:document.querySelector('#stamina-fill'),focus:document.querySelector('#focus-fill'),souls:document.querySelector('#souls'),flasks:document.querySelector('#flasks'),boss:document.querySelector('#boss-hud'),bossFill:document.querySelector('#boss-fill'),lock:document.querySelector('#lock-indicator'),prompt:document.querySelector('#interact-prompt'),feed:document.querySelector('#combat-feed'),toast:document.querySelector('#toast'),title:document.querySelector('#title-screen'),pause:document.querySelector('#pause-screen'),death:document.querySelector('#death-screen'),crosshair:document.querySelector('#crosshair')};
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9ca39a);scene.fog=new THREE.FogExp2(0x92988d,.022);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.outputColorSpace=THREE.SRGBColorSpace;
scene.add(new THREE.HemisphereLight(0xb9c4c0,0x29251d,1.15));
const moon=new THREE.DirectionalLight(0xdce5df,2.1);moon.position.set(-12,23,9);moon.castShadow=true;moon.shadow.mapSize.set(2048,2048);moon.shadow.camera.left=-28;moon.shadow.camera.right=28;moon.shadow.camera.top=28;moon.shadow.camera.bottom=-28;moon.shadow.bias=-.00035;scene.add(moon);
const glow=new THREE.PointLight(0xd58b4f,30,18,2);glow.position.set(0,2.5,2.5);scene.add(glow);
const clock=new THREE.Clock();const world=new THREE.Group();scene.add(world);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={bark:mat(0x302d27),bark2:mat(0x443c30),stone:mat(0x55574e),stone2:mat(0x737064),dark:mat(0x191c19),steel:mat(0x9da39a,.32,.76),gold:mat(0xb69a60,.35,.68),cloth:mat(0x343936),red:mat(0x602f2a),skin:mat(0xb99d83),ash:mat(0x756f61),leaf:mat(0x333e35),leaf2:mat(0x45473a),ember: new THREE.MeshBasicMaterial({color:0xffa653}),bone:mat(0xb5aa8b),blackmetal:mat(0x292d2b,.38,.72)};
function mesh(geo,material,parent=world,pos=[0,0,0],scale){const o=new THREE.Mesh(geo,material);o.position.set(...pos);if(scale)o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function box(parent,material,pos,scale,rot){let o=mesh(new THREE.BoxGeometry(1,1,1),material,parent,pos,scale);if(rot)o.rotation.set(...rot);return o;}
function cylinder(parent,material,pos,r1,r2,h,segments=8){return mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,parent,pos);}
// Sculpted, softly undulating ground with a worn road through the forest.
const N=100,size=110,verts=[],colors=[],indices=[];const groundColor=new THREE.Color();
for(let z=0;z<=N;z++)for(let x=0;x<=N;x++){let wx=(x/N-.5)*size,wz=(z/N-.5)*size;let road=Math.exp(-Math.pow(wx-(Math.sin(wz*.16)*1.6),2)/8);let h=Math.sin(wx*.24)*.22+Math.cos(wz*.19)*.26+Math.sin(wx*.37+wz*.31)*.12+(Math.random()-.5)*.045;h+=Math.max(0,Math.abs(wx)-18)*.14;verts.push(wx,h,wz);let c=road?new THREE.Color(0x524b3b):new THREE.Color(0x26332c);c.lerp(new THREE.Color(0x424235),Math.random()*.42);colors.push(c.r,c.g,c.b);}
for(let z=0;z<N;z++)for(let x=0;x<N;x++){let a=z*(N+1)+x,b=a+1,c=a+N+1,d=c+1;indices.push(a,c,b,b,c,d);}
const groundGeo=new THREE.BufferGeometry();groundGeo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));groundGeo.setIndex(indices);groundGeo.computeVertexNormals();const ground=mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}),world);ground.receiveShadow=true;ground.castShadow=false;
// Pebbled ground scatter and remnants of a forgotten stone causeway.
for(let i=0;i<380;i++){let x=(Math.random()-.5)*44,z=(Math.random()-.5)*55;if(Math.abs(x)<2.7&&z<7&&z>-31)continue;let r=.08+Math.random()*.34;let rock=mesh(new THREE.DodecahedronGeometry(r,0),Math.random()>.5?mats.stone:mats.bark2,world,[x,Math.sin(x*.24)*.22+Math.cos(z*.19)*.26+r*.45,z],[1,.45+Math.random()*.5,.8]);rock.rotation.set(Math.random(),Math.random()*3,Math.random());rock.castShadow=false;}
for(let z=-34;z<12;z+=2.25){for(let side of [-1,1]){let x=side*(1.9+Math.random()*.22),h=.14+Math.random()*.08;let slab=box(world,Math.random()>.5?mats.stone2:mats.stone,[x,h,z],[1.6,.24,2.1],[0,(Math.random()-.5)*.04,0]);slab.rotation.y=(Math.random()-.5)*.06;}}
// Ancient boundary stones, leaning trees, hanging dead canopies.
for(let i=0;i<75;i++){let side=Math.random()<.5?-1:1;let z=-42+Math.random()*70;let x=side*(7+Math.random()*26);let h=5+Math.random()*8;let trunk=cylinder(world,i%4===0?mats.bark2:mats.bark,[x,h*.5-0.1,z],.18+Math.random()*.28,.34+Math.random()*.25,h,7);trunk.rotation.z=(Math.random()-.5)*.22;trunk.rotation.x=(Math.random()-.5)*.25;
 for(let b=0;b<3;b++){let branch=cylinder(world,mats.bark,[x+(Math.random()-.5)*2,h*.75+Math.random()*1.5,z+(Math.random()-.5)*2],.04,.14,2.8,5);branch.rotation.set(Math.random()*.7,0,(Math.random()-.5)*1.4);}
 for(let j=0;j<5;j++){let crown=mesh(new THREE.DodecahedronGeometry(1+Math.random()*1.25,1),Math.random()>.5?mats.leaf:mats.leaf2,world,[x+(Math.random()-.5)*3,h+Math.random()*2,z+(Math.random()-.5)*3],[1.35,.8,1]);crown.castShadow=true;}}
// distant broken chapel silhouette
for(let side of [-1,1]){let x=side*17,z=-27;box(world,mats.stone,[x,3,z],[2,6,2]);box(world,mats.stone2,[x,6.2,z],[2.5,.4,2.4]);box(world,mats.stone,[x+side*2.7,2.3,z+1],[1.2,4.6,1.2]);box(world,mats.stone2,[x+side*2.7,4.8,z+1],[1.7,.3,1.7]);}
// Shrine and animated ash flame.
const shrine=new THREE.Group();shrine.position.set(0,0,3);world.add(shrine);cylinder(shrine,mats.stone2,[0,.36,0],1.28,1.52,.72,8);cylinder(shrine,mats.stone,[0,.8,0],.95,1.23,.22,8);cylinder(shrine,mats.gold,[0,.96,0],.67,.67,.12,8);const shrineStem=cylinder(shrine,mats.blackmetal,[0,1.42,0],.12,.18,.9,8);cylinder(shrine,mats.gold,[0,1.89,0],.35,.12,.17,8);const flame=mesh(new THREE.IcosahedronGeometry(.28,2),new THREE.MeshBasicMaterial({color:0xffb95d}),shrine,[0,2.25,0],[.7,1.7,.7]);const flame2=mesh(new THREE.IcosahedronGeometry(.17,1),new THREE.MeshBasicMaterial({color:0xffe6a1}),shrine,[0,2.1,.02],[.7,1.35,.7]);
for(let i=0;i<8;i++){let a=i*Math.PI/4;let c=cylinder(shrine,mats.gold,[Math.cos(a)*.95,1.12,Math.sin(a)*.95],.035,.035,.55,5);c.rotation.z=Math.cos(a)*.7;c.rotation.x=Math.sin(a)*.7;}
// Low stone arches and scattered crypt pieces provide landmarks.
for(let z of [-8,-21,-34]){for(let side of [-1,1]){let x=side*(6+Math.random()*2);box(world,mats.stone,[x,1.15,z],[.65,2.3,.7],[0,0,(Math.random()-.5)*.1]);}box(world,mats.stone2,[0,2.34,z],[13,.32,.9],[0,0,(Math.random()-.5)*.04]);}
function makeHumanoid(isBoss=false){const root=new THREE.Group(),visual=new THREE.Group();root.add(visual);let s=isBoss?1.38:1;const torsoMat=isBoss?mats.blackmetal:mats.cloth;const torso=mesh(new THREE.CapsuleGeometry(.43*s,.66*s,5,8),torsoMat,visual,[0,1.27*s,0],[1,.95,.76]);mesh(new THREE.SphereGeometry(.48*s,10,8),isBoss?mats.blackmetal:mats.steel,visual,[0,1.66*s,0],[1,.65,.82]);mesh(new THREE.SphereGeometry(.23*s,10,8),isBoss?mats.blackmetal:mats.skin,visual,[0,2.05*s,0]);let head=mesh(new THREE.SphereGeometry(.22*s,12,10),isBoss?mats.blackmetal:mats.skin,visual,[0,2.17*s,0],[.87,1.03,.86]);
