function faceToward(root,target){let dx=target.x-root.position.x,dz=target.z-root.position.z;root.rotation.y=Math.atan2(-dx,-dz);}
function updateEnemy(e,dt,t){if(!e.alive)return;const root=e.rig.root,d=dist(root.position,playerRig.root.position),bossEngaged=e.isBoss&&d<19;if(e.isBoss&&d<21)showBoss();if(player.dead||paused)return;
 if(e.stagger>0){e.stagger-=dt;return;}
 if(e.attack>0){e.attack-=dt;e.rig.weapon.rotation.z=-.27-Math.sin((1-e.attack/(e.isBoss?1.35:1.05))*Math.PI)*1.75;if(e.attack<.24&&e.attack>0&&!e.hit){e.hit=true;if(d<(e.isBoss?2.45:1.75)){damagePlayer(e.isBoss?23:12);burst(playerRig.root.position.clone().add(new THREE.Vector3(0,1.3,0)),0xbd5945,15);}}if(e.attack<=0){e.hit=false;e.rig.weapon.rotation.z=-.27;e.attack=0;}return;}
 const active=e.isBoss?bossEngaged:d<10;if(active&&d>(e.isBoss?2.6:1.75)){let dx=playerRig.root.position.x-root.position.x,dz=playerRig.root.position.z-root.position.z,len=Math.hypot(dx,dz)||1,speed=e.isBoss?1.35:1.05;root.position.x+=dx/len*speed*dt;root.position.z+=dz/len*speed*dt;root.position.y=terrainY(root.position.x,root.position.z);faceToward(root,playerRig.root.position);e.rig.visual.position.y=Math.abs(Math.sin(t*7+(e.isBoss?0:1)))*.045;if(Math.random()<.018)burst(root.position.clone().add(new THREE.Vector3(0,1,0)),0x8e8270,2);}
 else if(active&&d<(e.isBoss?3.3:2.4)){faceToward(root,playerRig.root.position);e.attack=e.isBoss?1.35:1.05;e.hit=false;showBoss();if(e.isBoss)feed('THE WARDEN STIRS');}
 else if(!e.isBoss){let drift=Math.sin(t*.36+e.patrol.x)*.5;root.position.x=e.patrol.x+drift;faceToward(root,playerRig.root.position);}
 if(e.isBoss){e.rig.limbs[0].rotation.z=Math.sin(t*1.6)*.06;e.rig.limbs[1].rotation.z=-Math.sin(t*1.6)*.06;}}
function hurtEnemy(e,amount){if(!e.alive)return;e.hp=Math.max(0,e.hp-amount);e.stagger=e.isBoss?.27:.36;e.rig.root.position.x+=Math.sin(playerRig.root.rotation.y)*-.19;e.rig.root.position.z+=Math.cos(playerRig.root.rotation.y)*-.19;burst(e.rig.root.position.clone().add(new THREE.Vector3(0,1.5,0)),e.isBoss?0xdf8c56:0xbca77d,12);feed(`${amount} DAMAGE`);if(e.isBoss)ui.bossFill.style.width=`${e.hp/e.max*100}%`;if(e.hp<=0){e.alive=false;e.rig.root.visible=false;player.souls+=e.isBoss?850:120;player.focus=Math.min(100,player.focus+18);updateHud();if(e.isBoss){won=true;toast('THE ASHEN WARDEN FALLS · THE ROAD OPENS');feed('SENTINEL VANQUISHED');}else feed('HUSK VANQUISHED');}}
function playerLockVector(){return player.lockTarget?.rig.root.position.clone().sub(playerRig.root.position)||new THREE.Vector3(0,0,-1);}
function angleLerp(a,b,k){let d=((b-a+Math.PI)%(Math.PI*2)+Math.PI*2)%(Math.PI*2)-Math.PI;return a+d*Math.min(1,k);}
function updatePlayer(dt,t){if(player.dead)return;player.invuln=Math.max(0,player.invuln-dt);player.attack=Math.max(0,player.attack-dt);player.dodge=Math.max(0,player.dodge-dt);player.heal=Math.max(0,player.heal-dt);player.stamina=Math.min(100,player.stamina+(player.attack>0||player.dodge>0?0:21*dt));player.focus=Math.min(100,player.focus+2*dt);
 let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+mobile.x;let iz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+mobile.z;let mag=Math.hypot(ix,iz);if(mag>1){ix/=mag;iz/=mag;mag=1;}
 const forward=new THREE.Vector3(-Math.sin(cameraYaw),0,-Math.cos(cameraYaw)),right=new THREE.Vector3(Math.cos(cameraYaw),0,-Math.sin(cameraYaw));let move=right.multiplyScalar(ix).add(forward.multiplyScalar(-iz));if(move.lengthSq()>0)move.normalize();let speed=player.dodge>0?8.7:(keys.ShiftLeft||keys.ShiftRight?4.6:3.15);if(player.dodge>0&&mag===0)move.set(-Math.sin(playerRig.root.rotation.y),0,-Math.cos(playerRig.root.rotation.y));if(player.attack>0)speed*=.45;
 if(mag>0||player.dodge>0){playerRig.root.position.x+=move.x*speed*dt;playerRig.root.position.z+=move.z*speed*dt;playerRig.root.position.x=THREE.MathUtils.clamp(playerRig.root.position.x,-39,39);playerRig.root.position.z=THREE.MathUtils.clamp(playerRig.root.position.z,-45,35);playerRig.root.position.y=terrainY(playerRig.root.position.x,playerRig.root.position.z);if(!player.locked&&player.dodge<=0)playerRig.root.rotation.y=Math.atan2(-move.x,-move.z);}
 if(player.locked&&player.lockTarget?.alive){let v=playerLockVector(),desired=Math.atan2(-v.x,-v.z);playerRig.root.rotation.y=angleLerp(playerRig.root.rotation.y,desired,dt*9);}
 player.anim+=dt*(mag?9:2.2);playerRig.visual.position.y=player.dodge>0?-.32:Math.abs(Math.sin(player.anim))*(mag?.065:.013);playerRig.limbs[0].rotation.x=Math.sin(player.anim)*mag*.65;playerRig.limbs[1].rotation.x=-Math.sin(player.anim)*mag*.65;playerRig.limbs[2].rotation.x=-Math.sin(player.anim)*mag*.55;playerRig.limbs[3].rotation.x=Math.sin(player.anim)*mag*.55;
 if(player.attack>0){let phase=1-player.attack/.62;playerRig.weapon.rotation.z=-.27-(phase<.35?phase*1.6:Math.sin(Math.min(1,(phase-.35)/.65)*Math.PI)*2.1);if(phase>.35&&phase<.53&&!player.attackHit){player.attackHit=true;let target=player.lockTarget?.alive?player.lockTarget:targetEnemy();if(target&&dist(playerRig.root.position,target.rig.root.position)<3.15){let f=new THREE.Vector3(-Math.sin(playerRig.root.rotation.y),0,-Math.cos(playerRig.root.rotation.y)),to=target.rig.root.position.clone().sub(playerRig.root.position).setY(0).normalize();if(f.dot(to)>.28)hurtEnemy(target,target.isBoss?32:42);}}}else playerRig.weapon.rotation.z=-.27;
 if(player.locked&&(!player.lockTarget||!player.lockTarget.alive||dist(playerRig.root.position,player.lockTarget.rig.root.position)>25)){player.locked=false;player.lockTarget=null;}
 nearestShrine=dist(playerRig.root.position,shrine.position)<2.9;ui.prompt.classList.toggle('visible',nearestShrine);if(dist(playerRig.root.position,boss.rig.root.position)<18&&boss.alive)showBoss();updateHud();}
function updateCamera(dt){const p=playerRig.root.position,back=new THREE.Vector3(Math.sin(cameraYaw),0,Math.cos(cameraYaw)),distance=player.locked?6.7:7.8;let desired=new THREE.Vector3(p.x+back.x*distance,p.y+3.45+cameraPitch*5,p.z+back.z*distance);if(player.locked&&player.lockTarget?.alive){let target=player.lockTarget.rig.root.position;desired.lerp(new THREE.Vector3((p.x+target.x)/2+back.x*6.4,p.y+3.3,(p.z+target.z)/2+back.z*6.4),.28);}camera.position.lerp(desired,1-Math.exp(-dt*5.2));let look=p.clone().add(new THREE.Vector3(0,1.25,0));if(player.locked&&player.lockTarget?.alive)look.lerp(player.lockTarget.rig.root.position.clone().add(new THREE.Vector3(0,1.45,0)),.22);camera.lookAt(look);}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.userData.life-=dt;p.position.addScaledVector(p.userData.vel,dt);p.userData.vel.y-=3*dt;p.scale.multiplyScalar(Math.max(.01,1-dt*1.2));if(p.userData.life<=0){world.remove(p);p.geometry.dispose();particles.splice(i,1);}}}
const motes=[];for(let i=0;i<42;i++){let o=mesh(new THREE.SphereGeometry(.025+Math.random()*.025,5,4),new THREE.MeshBasicMaterial({color:Math.random()>.35?0xffbd72:0x9aa998,transparent:true,opacity:.65}),world,[(Math.random()-.5)*34,.5+Math.random()*5,-28+Math.random()*42]);motes.push({o,base:o.position.clone(),phase:Math.random()*8});}
function animate(){requestAnimationFrame(animate);let dt=Math.min(.04,clock.getDelta()),t=clock.elapsedTime;if(!paused){updatePlayer(dt,t);enemies.forEach(e=>updateEnemy(e,dt,t));updateParticles(dt);motes.forEach(m=>{m.o.position.y=m.base.y+Math.sin(t*.6+m.phase)*.38;m.o.position.x=m.base.x+Math.sin(t*.25+m.phase)*.25;m.o.material.opacity=.35+Math.sin(t*1.4+m.phase)*.28;});flame.scale.y=1.6+Math.sin(t*11)*.3;flame2.scale.y=1.2+Math.cos(t*13)*.24;glow.intensity=25+Math.sin(t*8)*5;shrine.rotation.y=Math.sin(t*.3)*.03;}updateCamera(dt);renderer.render(scene,camera);}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);});
updateHud();updateCamera(1);animate();

